1	// The home screen and the app's signature interaction: a blank page you can
2	// type on immediately. Swiping up files the page away (the note slides off the
3	// top) and a fresh blank page is ready underneath — same gesture as the
4	// original app. Notes land in Feed via the desktop-compatible core.
5	//
6	// Gesture model on the page (all raced, direction- and position-separated so
7	// they don't fight the TextInput's own scroll):
8	//   swipe UP   → file the page + open a fresh one, but only once you've
9	//                scrolled the note to the BOTTOM. A rounded "tongue" stretches
10	//                from the bottom edge as you pull; past the arm threshold it
11	//                turns accent (release = commit).
12	//   swipe DOWN → dismiss the keyboard, but only when the note is at the TOP
13	//                (otherwise a downward drag scrolls the note up as usual).
14	//   swipe LEFT → pull the Sync screen in behind a preview (unchanged).
15	// The keyboard never covers the caret: the page's bottom padding tracks the
16	// keyboard height (like Apple Notes) so the text always sits above it.
17	
18	import { Ionicons } from "@expo/vector-icons";
19	import { useNavigation } from "@react-navigation/native";
20	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
21	import { useEffect, useMemo, useRef, useState } from "react";
22	import {
23	  Keyboard,
24	  type LayoutChangeEvent,
25	  type NativeSyntheticEvent,
26	  StyleSheet,
27	  Text,
28	  TextInput,
29	  type TextInputScrollEventData,
30	  useWindowDimensions,
31	  View,
32	} from "react-native";
33	import { Gesture, GestureDetector } from "react-native-gesture-handler";
34	import Animated, {
35	  Easing,
36	  Extrapolation,
37	  interpolate,
38	  interpolateColor,
39	  runOnJS,
40	  useAnimatedKeyboard,
41	  useAnimatedStyle,
42	  useSharedValue,
43	  withSpring,
44	  withTiming,
45	} from "react-native-reanimated";
46	import { useSafeAreaInsets } from "react-native-safe-area-context";
47	
48	import * as core from "@typenotes/mobile-core/core-api";
49	
50	import { CaptureSession } from "../lib/capture";
51	import { useClearInstantParam, type RootStackParamList } from "../navigation";
52	import { useNotesStore } from "../state/notes-store";
53	import { useTheme } from "../theme";
54	import { DictationButton } from "../ui/dictation-button";
55	import { ToolbarButton } from "../ui/toolbar-button";
56	
57	// Flick velocity (px/s, upward) that files the page regardless of distance.
58	const SWIPE_VELOCITY = -900;
59	
60	// The swipe-up "tongue": a rounded tab that stretches up from the bottom edge
61	// as you drag. It arms (turns accent, chevron flips to the filled state) once
62	// the drag passes ARM_PULL — release then files the page.
63	const TONGUE_WIDTH = 128;
64	const MAX_PULL = 88;
65	const ARM_PULL = 64;
66	// The page itself lifts a little as you pull, for a touch of physicality.
67	const PAGE_FOLLOW = 0.4;
68	
69	// The finger-driven swipe to the sync screen (same mechanics as the menu's
70	// swipe-to-capture in menu-screen.tsx): release past this fraction of the
71	// screen (or a faster leftward flick) commits, the page parallaxes left
72	// behind the incoming preview.
73	const SYNC_OPEN_PROGRESS = 0.3;
74	const SYNC_OPEN_VELOCITY = -500;
75	const SYNC_PARALLAX = 0.3;
76	
77	export const CaptureScreen = () => {
78	  const theme = useTheme();
79	  const insets = useSafeAreaInsets();
80	  const navigation =
81	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
82	  const { height, width } = useWindowDimensions();
83	
84	  const [text, setText] = useState("");
85	  const [pageKey, setPageKey] = useState(0);
86	  const [iconsVisible, setIconsVisible] = useState(true);
87	  const [recordingActive, setRecordingActive] = useState(false);
88	  const iconsOpacity = useSharedValue(1);
89	  const inputRef = useRef<TextInput>(null);
90	
91	  // The keyboard height (0 when hidden) as a UI-thread shared value; the page
92	  // padding and the floating controls ride it so nothing hides under the
93	  // keyboard.
94	  const keyboard = useAnimatedKeyboard();
95	
96	  // Whether the note is scrolled to its top / bottom edge. A blank or
97	  // short note (nothing to scroll) is at both. These gate the vertical
98	  // gestures so switching-to-next and dismissing-keyboard don't fight the
99	  // note's own scrolling: you can only file the page from the bottom, and
100	  // only dismiss the keyboard from the top. Kept in refs too so onScroll
101	  // can flip them without re-reading state.
102	  const [atTop, setAtTop] = useState(true);
103	  const [atBottom, setAtBottom] = useState(true);
104	  const [keyboardVisible, setKeyboardVisible] = useState(false);
105	  const atTopRef = useRef(true);
106	  const atBottomRef = useRef(true);
107	  // The multiline input's onScroll only reports contentOffset, so its viewport
108	  // and content heights are tracked separately (onLayout / onContentSizeChange)
109	  // and combined to decide whether we're at an edge.
110	  const scrollYRef = useRef(0);
111	  const viewportHRef = useRef(0);
112	  const contentHRef = useRef(0);
113	
114	  const session = useMemo(
115	    () =>
116	      new CaptureSession({
117	        createNote: async (content) => (await core.createNote({ content })).path,
118	        writeNote: core.writeNote,
119	        deleteNote: (path) => core.deleteItems([path]),
120	      }),
121	    []
122	  );
123	
124	  // Flush the draft when the screen loses focus (navigation away).
125	  useEffect(
126	    () => navigation.addListener("blur", () => void session.flush()),
127	    [navigation, session]
128	  );
129	
130	  // Keep the keyboard-visible flag current for the dismiss gesture's enabled
131	  // state (a JS boolean — the animated height above drives layout instead).
132	  useEffect(() => {
133	    const show = Keyboard.addListener("keyboardDidShow", () =>
134	      setKeyboardVisible(true)
135	    );
136	    const hide = Keyboard.addListener("keyboardDidHide", () =>
137	      setKeyboardVisible(false)
138	    );
139	    return () => {
140	      show.remove();
141	      hide.remove();
142	    };
143	  }, []);
144	
145	  // The menu's swipe may have pushed this page with animation:none (its
146	  // preview already played the transition) — flip the flag back once the
147	  // push settles so the later pop / back swipe animates natively.
148	  useClearInstantParam();
149	
150	  const translateY = useSharedValue(0);
151	  // 0..MAX_PULL — how far the swipe-up tongue has stretched.
152	  const pull = useSharedValue(0);
153	
154	  // Wrap Keyboard.dismiss so the worklet captures this plain closure rather
155	  // than the bare method — passing Keyboard.dismiss straight to runOnJS makes
156	  // worklets try to copy its owner (KeyboardImpl), which it can't serialize.
157	  const dismissKeyboard = () => Keyboard.dismiss();
158	
159	  const resetScrollEdges = () => {
160	    scrollYRef.current = 0;
161	    contentHRef.current = 0;
162	    atTopRef.current = true;
163	    atBottomRef.current = true;
164	    setAtTop(true);
165	    setAtBottom(true);
166	  };
167	
168	  const commitPage = () => {
169	    void session.commit().then((path) => {
170	      if (path) {
171	        void useNotesStore.getState().refresh();
172	      }
173	    });
174	    // Remount the input so the new blank page appears with no text flash.
175	    setText("");
176	    setPageKey((key) => key + 1);
177	    translateY.value = 0;
178	    pull.value = 0;
179	    resetScrollEdges();
180	    showIcons();
181	  };
182	
183	  const showIcons = () => {
184	    setIconsVisible(true);
185	    iconsOpacity.value = withTiming(1, { duration: 180 });
186	  };
187	
188	  const hideIcons = () => {
189	    setIconsVisible(false);
190	    iconsOpacity.value = withTiming(0, { duration: 180 });
191	  };
192	
193	  // Recompute the scroll edges from the latest scroll offset + viewport/content
194	  // heights; only re-render when an edge flag flips so typing/scrolling stays
195	  // cheap. A note that fits its viewport is at both edges.
196	  const recomputeScrollEdges = () => {
197	    const scrollY = scrollYRef.current;
198	    const maxScroll = Math.max(0, contentHRef.current - viewportHRef.current);
199	    const top = scrollY <= 4;
200	    const bottom = scrollY >= maxScroll - 6;
201	    if (top !== atTopRef.current) {
202	      atTopRef.current = top;
203	      setAtTop(top);
204	    }
205	    if (bottom !== atBottomRef.current) {
206	      atBottomRef.current = bottom;
207	      setAtBottom(bottom);
208	    }
209	  };
210	
211	  const onScroll = (event: NativeSyntheticEvent<TextInputScrollEventData>) => {
212	    scrollYRef.current = event.nativeEvent.contentOffset.y;
213	    recomputeScrollEdges();
214	  };
215	  const onInputLayout = (event: LayoutChangeEvent) => {
216	    viewportHRef.current = event.nativeEvent.layout.height;
217	    recomputeScrollEdges();
218	  };
219	  const onContentSizeChange = (
220	    event: NativeSyntheticEvent<{ contentSize: { width: number; height: number } }>
221	  ) => {
222	    contentHRef.current = event.nativeEvent.contentSize.height;
223	    recomputeScrollEdges();
224	  };
225	
226	  // A clear downward drag tucks the keyboard away (the input regains it on the
227	  // next tap). Gated to the top of the note + keyboard-up so a downward drag
228	  // elsewhere scrolls the note instead of stealing it.
229	  const dismissKeyboardPan = Gesture.Pan()
230	    .enabled(keyboardVisible && atTop)
231	    .activeOffsetY(18)
232	    .failOffsetY(-14)
233	    .failOffsetX([-30, 30])
234	    .onStart(() => {
235	      runOnJS(dismissKeyboard)();
236	    });
237	
238	  // Conceptually the sync screen sits to the RIGHT of the capture page (the
239	  // menu is to the left): a clearly-leftward drag pulls it in with the
240	  // finger, exactly like the menu's swipe-to-capture — a preview overlay
241	  // (background + a replica of Sync's native header) rides the finger, and
242	  // committing pushes the real screen underneath it with animation:none.
243	  // Rightward drags stay with the native back swipe, vertical ones with the
244	  // page gestures. Sync's body is dynamic so the preview can't replicate it;
245	  // only the chrome matches and the content appears at the swap.
246	  const syncProgress = useSharedValue(0);
247	
248	  const syncDepthStyle = useAnimatedStyle(() => ({
249	    transform: [{ translateX: -width * SYNC_PARALLAX * syncProgress.value }],
250	  }));
251	  const syncDimStyle = useAnimatedStyle(() => ({
252	    opacity: 0.08 * syncProgress.value,
253	  }));
254	  const syncPreviewStyle = useAnimatedStyle(() => ({
255	    transform: [{ translateX: width * (1 - syncProgress.value) }],
256	    // Parked exactly one screen-width right; hide it whenever this gesture
257	    // isn't driving it or native pops (which parallax this whole screen)
258	    // would poke its edge into the frame — same trap as the menu's preview.
259	    opacity: syncProgress.value > 0 ? 1 : 0,
260	  }));
261	
262	  const openSyncBehindPreview = () => {
263	    navigation.navigate("Sync", { instant: true });
264	    // Drop the preview once the pushed screen is attached on top (no native
265	    // "attached" signal with animation:none — the delay outlives the mount).
266	    setTimeout(() => {
267	      syncProgress.value = 0;
268	    }, 400);
269	  };
270	
271	  const swipeToSync = Gesture.Pan()
272	    .activeOffsetX(-24)
273	    .failOffsetX(24)
274	    .failOffsetY([-24, 24])
275	    .onStart(() => {
276	      // The capture input stays mounted (and focused) beneath the pushed
277	      // screen and would otherwise keep the keyboard up over it.
278	      runOnJS(dismissKeyboard)();
279	    })
280	    .onUpdate((event) => {
281	      syncProgress.value = Math.min(1, Math.max(0, -event.translationX / width));
282	    })
283	    .onEnd((event) => {
284	      const shouldOpen =
285	        syncProgress.value > SYNC_OPEN_PROGRESS ||
286	        event.velocityX < SYNC_OPEN_VELOCITY;
287	      if (shouldOpen) {
288	        syncProgress.value = withTiming(
289	          1,
290	          { duration: 160, easing: Easing.out(Easing.cubic) },
291	          (finished) => {
292	            if (finished) {
293	              runOnJS(openSyncBehindPreview)();
294	            }
295	          }
296	        );
297	      } else {
298	        syncProgress.value = withTiming(0, { duration: 180 });
299	      }
300	    });
301	
302	  // Swipe up to file the page + open a fresh one. Enabled only at the bottom of
303	  // the note so a partly-scrolled long note keeps scrolling under the finger;
304	  // once at the bottom, an upward drag stretches the tongue and, past the arm
305	  // threshold (or a fast flick), files the page.
306	  const swipeToFile = Gesture.Pan()
307	    .enabled(atBottom)
308	    // Only claim clearly-upward drags; leave taps and downward scrolling to
309	    // the text input, and mostly-horizontal drags to the navigator's
310	    // full-screen back swipe / the sync swipe.
311	    .activeOffsetY([-18, Number.MAX_SAFE_INTEGER])
312	    .failOffsetX([-40, 40])
313	    .failOffsetY(14)
314	    .onUpdate((event) => {
315	      const dragUp = Math.max(0, -event.translationY);
316	      pull.value = Math.min(MAX_PULL, dragUp);
317	      translateY.value = -pull.value * PAGE_FOLLOW;
318	    })
319	    .onEnd((event) => {
320	      const armed = pull.value >= ARM_PULL || event.velocityY < SWIPE_VELOCITY;
321	      if (armed) {
322	        runOnJS(dismissKeyboard)();
323	        pull.value = withTiming(0, { duration: 200 });
324	        translateY.value = withTiming(-height, { duration: 220 }, (finished) => {
325	          if (finished) {
326	            runOnJS(commitPage)();
327	          }
328	        });
329	      } else {
330	        pull.value = withTiming(0, { duration: 160 });
331	        translateY.value = withSpring(0, { damping: 20, stiffness: 300 });
332	      }
333	    });
334	
335	  // The page follows the finger a little and its bottom padding tracks the
336	  // keyboard so the caret is never covered.
337	  const pageStyle = useAnimatedStyle(() => ({
338	    transform: [{ translateY: translateY.value }],
339	    paddingBottom: keyboard.height.value,
340	  }));
341	
342	  const toolbarStyle = useAnimatedStyle(() => ({
343	    opacity: iconsOpacity.value,
344	  }));
345	  // The dictation FAB floats just above the keyboard when it's up.
346	  const fabStyle = useAnimatedStyle(() => ({
347	    opacity: iconsOpacity.value,
348	    transform: [{ translateY: -keyboard.height.value }],
349	  }));
350	
351	  // The tongue: a rounded tab whose height is the pull distance, anchored just
352	  // above the keyboard (or the safe-area bottom). It fills toward accent and
353	  // pops as it arms.
354	  const tongueTrackStyle = useAnimatedStyle(() => ({
355	    bottom: Math.max(keyboard.height.value, insets.bottom) + 6,
356	    opacity: pull.value > 1 ? 1 : 0,
357	  }));
358	  const tongueStyle = useAnimatedStyle(() => ({
359	    height: pull.value,
360	    backgroundColor: interpolateColor(
361	      pull.value,
362	      [ARM_PULL - 16, ARM_PULL],
363	      [theme.colors.surface, theme.colors.accent]
364	    ),
365	    borderColor: interpolateColor(
366	      pull.value,
367	      [ARM_PULL - 16, ARM_PULL],
368	      [theme.colors.border, theme.colors.accent]
369	    ),
370	    transform: [
371	      {
372	        scale: interpolate(
373	          pull.value,
374	          [ARM_PULL - 16, ARM_PULL],
375	          [1, 1.06],
376	          Extrapolation.CLAMP
377	        ),
378	      },
379	    ],
380	  }));
381	  const chevronRestStyle = useAnimatedStyle(() => ({
382	    opacity: interpolate(
383	      pull.value,
384	      [ARM_PULL - 16, ARM_PULL],
385	      [1, 0],
386	      Extrapolation.CLAMP
387	    ),
388	  }));
389	  const chevronArmedStyle = useAnimatedStyle(() => ({
390	    opacity: interpolate(
391	      pull.value,
392	      [ARM_PULL - 16, ARM_PULL],
393	      [0, 1],
394	      Extrapolation.CLAMP
395	    ),
396	  }));
397	
398	  const onChange = (value: string) => {
399	    setText(value);
400	    session.onChange(value);
401	    // Keep the page uncluttered while writing; tapping back into the text
402	    // brings the hamburger/mic buttons back. While a dictation is running the
403	    // stop button must stay reachable, so nothing fades.
404	    if (iconsVisible && !recordingActive) {
405	      hideIcons();
406	    }
407	  };
408	
409	  return (
410	    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
411	      <Animated.View style={[styles.depth, syncDepthStyle]}>
412	      <GestureDetector
413	        gesture={Gesture.Race(swipeToFile, dismissKeyboardPan, swipeToSync)}
414	      >
415	        <Animated.View
416	          style={[
417	            styles.page,
418	            { backgroundColor: theme.colors.background, paddingTop: insets.top + 12 },
419	            pageStyle,
420	          ]}
421	        >
422	          <TextInput
423	            key={pageKey}
424	            ref={inputRef}
425	            style={[styles.input, { color: theme.colors.text }]}
426	            value={text}
427	            onChangeText={onChange}
428	            onPressIn={showIcons}
429	            onScroll={onScroll}
430	            onLayout={onInputLayout}
431	            onContentSizeChange={onContentSizeChange}
432	            placeholder="Start typing…"
433	            placeholderTextColor={theme.colors.secondaryText}
434	            multiline
435	            scrollEnabled
436	            textAlignVertical="top"
437	            keyboardAppearance={theme.dark ? "dark" : "light"}
438	          />
439	          {/* "swipe up for a new page" hint hidden per feedback — the gesture
440	              still works, we just don't want to show the label. */}
441	        </Animated.View>
442	      </GestureDetector>
443	
444	      {/* The swipe-up tongue: stretches from the bottom edge as you pull, and
445	          turns accent once it's armed to file the page. */}
446	      <Animated.View
447	        pointerEvents="none"
448	        style={[styles.tongueTrack, tongueTrackStyle]}
449	      >
450	        <Animated.View style={[styles.tongue, tongueStyle]}>
451	          <Animated.View style={[styles.chevron, chevronRestStyle]}>
452	            <Ionicons
453	              name="chevron-up"
454	              size={22}
455	              color={theme.colors.secondaryText}
456	            />
457	          </Animated.View>
458	          <Animated.View style={[styles.chevron, chevronArmedStyle]}>
459	            <Ionicons name="chevron-up" size={22} color="#ffffff" />
460	          </Animated.View>
461	        </Animated.View>
462	      </Animated.View>
463	
464	      <Animated.View
465	        pointerEvents={iconsVisible ? "auto" : "none"}
466	        style={[styles.toolbarLeft, { top: insets.top + 8 }, toolbarStyle]}
467	      >
468	        <ToolbarButton
469	          icon="menu-outline"
470	          // popTo, not navigate: the menu is the stack root below this
471	          // screen, and v7 navigate would push a second Menu on top (sliding
472	          // in from the right) instead of popping back to it.
473	          onPress={() => navigation.popTo("Menu")}
474	        />
475	      </Animated.View>
476	      <Animated.View
477	        pointerEvents={iconsVisible ? "auto" : "none"}
478	        style={[styles.fab, { bottom: insets.bottom + 36 }, fabStyle]}
479	      >
480	        <DictationButton onRecordingChange={setRecordingActive} />
481	      </Animated.View>
482	      </Animated.View>
483	
484	      {/* Native-push depth cues for the sync swipe: the page dims while the
485	          sync preview rides in above it (see swipeToSync). */}
486	      <Animated.View
487	        pointerEvents="none"
488	        style={[StyleSheet.absoluteFill, styles.syncDim, syncDimStyle]}
489	      />
490	      <Animated.View
491	        pointerEvents="none"
492	        style={[
493	          styles.syncPreview,
494	          { backgroundColor: theme.colors.background },
495	          syncPreviewStyle,
496	        ]}
497	      >
498	        {/* Replica of Sync's native header (title + chevron-only back) so
499	            the instant swap after commit only pops the body in. */}
500	        <View style={{ paddingTop: insets.top }}>
501	          <View style={styles.syncPreviewBar}>
502	            <Ionicons
503	              name="chevron-back"
504	              size={26}
505	              color={theme.colors.text}
506	              style={styles.syncPreviewBack}
507	            />
508	            <Text style={[styles.syncPreviewTitle, { color: theme.colors.text }]}>
509	              Sync
510	            </Text>
511	          </View>
512	        </View>
513	      </Animated.View>
514	    </View>
515	  );
516	};
517	
518	const styles = StyleSheet.create({
519	  root: { flex: 1 },
520	  depth: { flex: 1 },
521	  syncDim: { backgroundColor: "#000" },
522	  syncPreview: {
523	    position: "absolute",
524	    top: 0,
525	    left: 0,
526	    right: 0,
527	    bottom: 0,
528	    shadowColor: "#000",
529	    shadowOffset: { width: -4, height: 0 },
530	    shadowOpacity: 0.12,
531	    shadowRadius: 10,
532	  },
533	  // Mirrors the native-stack header: 44pt bar, centered 17pt semibold title,
534	  // chevron-only back at the left edge.
535	  syncPreviewBar: { height: 44, alignItems: "center", justifyContent: "center" },
536	  syncPreviewBack: { position: "absolute", left: 8, top: 9 },
537	  syncPreviewTitle: { fontSize: 17, fontWeight: "600" },
538	  page: { flex: 1, paddingHorizontal: 20 },
539	  input: {
540	    flex: 1,
541	    fontSize: 17,
542	    lineHeight: 26,
543	    paddingTop: 44,
544	  },
545	  // Full-width, bottom-anchored track that centers the tongue tab.
546	  tongueTrack: {
547	    position: "absolute",
548	    left: 0,
549	    right: 0,
550	    alignItems: "center",
551	  },
552	  // A rounded tab (semicircular cap) that stretches upward with the pull.
553	  tongue: {
554	    width: TONGUE_WIDTH,
555	    borderTopLeftRadius: TONGUE_WIDTH / 2,
556	    borderTopRightRadius: TONGUE_WIDTH / 2,
557	    borderWidth: StyleSheet.hairlineWidth,
558	    overflow: "hidden",
559	  },
560	  // The two chevrons (rest + armed) stack at the tab's crest and cross-fade.
561	  chevron: {
562	    position: "absolute",
563	    top: 9,
564	    left: 0,
565	    right: 0,
566	    alignItems: "center",
567	  },
568	  fab: {
569	    position: "absolute",
570	    right: 32,
571	    alignItems: "flex-end",
572	  },
573	  toolbarLeft: {
574	    position: "absolute",
575	    left: 20,
576	    flexDirection: "row",
577	  },
578	});
579

