1	// The floating dictation button (bottom-right of the capture page) — this
2	// replaced the old Record screen. Tap to start, tap again to stop; or press
3	// and hold to record only while held (release = stop & save, handy for quick
4	// 5–10s clips). Saving goes through the core (Feed note + audio file +
5	// transcription_status: pending), then queues transcription according to the
6	// working folder's transcription_mode:
7	//
8	//   assemblyai → cloud queue now, on this device
9	//   native     → on-device speech recognition via the expo-speech-recognition
10	//                provider (lib/native-transcription), run by the core's queue
11	//   desktop    → stays pending; a synced desktop picks it up (local Whisper)
12	//   off        → stays pending until triggered manually
13	
14	import { Ionicons } from "@expo/vector-icons";
15	import {
16	  AudioModule,
17	  RecordingPresets,
18	  setAudioModeAsync,
19	  useAudioRecorder,
20	  useAudioRecorderState,
21	} from "expo-audio";
22	import * as FileSystem from "expo-file-system/legacy";
23	import { useEffect, useRef, useState } from "react";
24	import { Pressable, StyleSheet, Text, View } from "react-native";
25	
26	import * as core from "@typenotes/mobile-core/core-api";
27	import { getErrorMessage } from "@typenotes/shared/errors";
28	import {
29	  effectiveTranscriptionMode,
30	  type TranscriptionMode,
31	} from "@typenotes/shared/types";
32	
33	import { nativeTranscriptionProvider } from "../lib/native-transcription";
34	import { useNotesStore } from "../state/notes-store";
35	import { activeProfile, useSettingsStore } from "../state/settings-store";
36	import { useTheme } from "../theme";
37	
38	// A press released after this long counts as "hold to record" and stops on
39	// release; a quicker press is a tap that leaves the recording running.
40	const HOLD_TO_RECORD_MS = 400;
41	const STATUS_VISIBLE_MS = 4000;
42	
43	const MODE_SAVED_DETAIL: Record<TranscriptionMode, string> = {
44	  assemblyai: "Saved — transcribing via AssemblyAI",
45	  native: "Saved — transcribing on this device",
46	  desktop: "Saved — your desktop will transcribe it",
47	  off: "Saved",
48	};
49	
50	type PillStatus = { kind: "success" | "error"; text: string };
51	
52	export const DictationButton = ({
53	  onRecordingChange,
54	}: {
55	  onRecordingChange?: (recording: boolean) => void;
56	}) => {
57	  const theme = useTheme();
58	  const recorder = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
59	  const recorderState = useAudioRecorderState(recorder);
60	
61	  const [busy, setBusy] = useState(false);
62	  const [status, setStatus] = useState<PillStatus | null>(null);
63	  const statusTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
64	
65	  // Start is async (permission prompt, prepare) — a hold can end before it
66	  // finishes, so stopAndSave awaits the in-flight start before stopping.
67	  const startPromise = useRef<Promise<void> | null>(null);
68	  const pressInAt = useRef(0);
69	  const pressStartedRecording = useRef(false);
70	
71	  const snapshot = useSettingsStore((s) => s.snapshot);
72	  const settings = activeProfile(snapshot)?.settings;
73	  const mode: TranscriptionMode = settings
74	    ? effectiveTranscriptionMode(settings)
75	    : "desktop";
76	
77	  useEffect(() => {
78	    onRecordingChange?.(recorderState.isRecording);
79	  }, [recorderState.isRecording, onRecordingChange]);
80	
81	  const showStatus = (next: PillStatus) => {
82	    if (statusTimer.current) {
83	      clearTimeout(statusTimer.current);
84	    }
85	    setStatus(next);
86	    statusTimer.current = setTimeout(() => setStatus(null), STATUS_VISIBLE_MS);
87	  };
88	  useEffect(
89	    () => () => {
90	      if (statusTimer.current) {
91	        clearTimeout(statusTimer.current);
92	      }
93	    },
94	    []
95	  );
96	
97	  const start = async () => {
98	    const permission = await AudioModule.requestRecordingPermissionsAsync();
99	    if (!permission.granted) {
100	      throw new Error("Microphone permission denied — enable it in system settings.");
101	    }
102	    await setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
103	    await recorder.prepareToRecordAsync();
104	    recorder.record();
105	  };
106	
107	  const stopAndSave = async () => {
108	    setBusy(true);
109	    try {
110	      await startPromise.current;
111	      await recorder.stop();
112	      const uri = recorder.uri;
113	      if (!uri) {
114	        throw new Error("Recorder produced no file.");
115	      }
116	      const audioBase64 = await FileSystem.readAsStringAsync(uri, {
117	        encoding: "base64",
118	      });
119	      await core.saveAudioRecording({
120	        audio_base64: audioBase64,
121	        mime_type: "audio/mp4",
122	      });
123	
124	      let detail = MODE_SAVED_DETAIL[mode];
125	      if (mode === "assemblyai") {
126	        try {
127	          await core.queueRecordingTranscriptions();
128	        } catch (queueError) {
129	          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
130	        }
131	      } else if (mode === "native") {
132	        try {
133	          await core.queueProviderTranscriptions(nativeTranscriptionProvider);
134	        } catch (queueError) {
135	          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
136	        }
137	      }
138	      showStatus({ kind: "success", text: detail });
139	      void useNotesStore.getState().refresh();
140	    } catch (err) {
141	      showStatus({ kind: "error", text: getErrorMessage(err) });
142	    } finally {
143	      startPromise.current = null;
144	      setBusy(false);
145	      // Leave the play-and-record session so playback routes normally again.
